   228→          <v-card-text>
   229→            <v-select v-model="selectedDuplicatePage" :items="pdfPages" variant="outlined" density="compact"
   230→              placeholder="Selecciona la página"></v-select>
   231→          </v-card-text>
   232→          <v-card-actions class="d-flex justify-center">
   233→            <v-btn @click="showDuplicateDialog = false" class="text-none" rounded variant="outlined">Cancelar</v-btn>
   234→            <v-btn rounded color="#007AFF" class="text-none" @click="confirmDuplicateField" variant="flat">Confirmar</v-btn>
   235→          </v-card-actions>
