   167→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields) { 
   168→    const pdfDoc = pdfBuffer;
   169→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
   170→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
   171→
   172→    await Promise.all(fields.map(async (field) => {
   173→        const { pageNumber, top, left, width, height, name } = field;
   174→        const page = pdfDoc.getPage(pageNumber - 1);
   175→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12); 
   176→        const textHeight = helveticaFont.heightAtSize(12); 
   177→
   178→        const x = left + (width / 2) - (textWidth / 2) - 15;
   179→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
   180→
   181→        page.drawText(name, {
   182→            x: x,
   183→            y: y + 8,
   184→            size: 12,
   185→            font: helveticaFont
   186→        });
   187→        
   188→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
   189→
   190→        if (signer) {
   191→            const fullName = `${signer.nombres} ${signer.apellidos}`;
   192→            const docType = await getDocumentTypeName(signer.tipo_documento);
   193→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
   194→
   195→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
   196→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
   197→            
   198→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
   199→            
   200→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
   201→            
   202→            page.drawText(fullName, {
   203→                x: xFullName,
   204→                y: y - textHeight - 8,
   205→                size: 10,
   206→                font: timesRomanFont
   207→            });
   208→            
   209→            page.drawText(docTypeAndNumber, {
   210→                x: xDocTypeAndNumber,
   211→                y: y - textHeight - 22,
   212→                size: 10,
   213→                font: timesRomanFont
   214→            });
   215→        }
   216→    }));
   217→
   218→    return await pdfDoc.save();
   219→}
