"use strict";

const { PrismaClient } = require("@prisma/client");
const db = new PrismaClient();
const axios = require('axios');
const { logHistory } = require('./folder_packages.controller.js');
const { checkUserPermissions } = require("./permissions_folder.controller");

require("dotenv").config();

async function getDocumentsPackages(req, res) {
    try {
        const company_id = parseInt(req.params.company_id);
        const userId = req.params.user_id; 
        const page = req.params.page ? parseInt(req.params.page) : 1;
        const perPage = req.params.itemsPerPage ? parseInt(req.params.itemsPerPage) : 10;
        const skip = (page - 1) * perPage;

        const where = {
            company_id: company_id,
            deleted: false,
        };

        const whereCount = {
            ...where,
            parent_id: null,
        };

        const [total, results] = await db.$transaction([
            db.document_packages_header.count({ where: whereCount }),
            db.document_packages_header.findMany({
                where,
                skip,
                take: perPage,
                orderBy: { name: 'desc' },
                include: {
                    package_features: true, 
                    group_signers: true, 
                    group_recipients: { select: { email: true } },
                    documents: {
                        select: {
                            id: true,
                            name: true,
                            fields: true,
                            signers_fields: true,
                            template_version_id: true,
                            content: true,
                            created_at: true,
                            template: {
                                select: {
                                    tpl_name: true,
                                    visibility: true,
                                    fields_description: true,
                                }
                            }
                        },
                        where: { active: "1"}
                    }
                }
            })
        ]);

        if (results.length === 0) {
            return res.status(200).send({ status: true, total: 0, data: [] });
        }

        const dataPromises = results.map(async (item) => {

            const signers = item.group_signers.map(gs => ({
                signers_user_id: gs.user_id,
                signers_order: gs.order,
                is_default_sign: gs.is_default_sign,
                days_to_sign: gs.days_to_sign,
            }));

            const recipients = item.group_recipients.map(gr => ({ email: gr.email.trim() }));

            const hasFeature = (id) => item.package_features.some(f => f.feature_id === id && f.status === 1);
            const photo_control = hasFeature(1);
            const geolocation_control = hasFeature(2);
            const validation_code_control = hasFeature(3);

            const details = item.is_pdf
                ? item.documents.map(detail => ({
                    id: detail.id,
                    name: detail.name || detail.template?.tpl_name || "",
                    url: detail.content || null,
                    created_at: detail.created_at,
                  }))
                : item.documents.map(detail => {
                    const tmpFields = detail.fields ? detail.fields.split("|") : [];
                    const tmpSigners = detail.signers_fields ? detail.signers_fields.split("|") : [];
                    const obj = {};
                    if (tmpFields.some(f => f !== '')) {
                        tmpFields.forEach(fieldName => { obj[fieldName] = ""; });
                    }
                    let objSigners = null;
                    if (tmpSigners.some(s => s !== '')) {
                        objSigners = {};
                        tmpSigners.forEach(signerField => {
                            objSigners[signerField] = {     
                                nombres: "",
                                apellidos: "",
                                correo: "",
                                documento: "",
                                tipo_documento: "",
                            };
                        });
                    }
                    let descriptionsObj = {};
                    if (detail.template?.fields_description) {
                        try { descriptionsObj = JSON.parse(detail.template.fields_description); } 
                        catch (e) { console.error("Error al parsear fields_description:", e); }
                    }
                    return {
                        id_detalle_grupo_documento: detail.id,
                        name: detail.template?.tpl_name || "",
                        fields: obj,
                        fields_description: descriptionsObj,
                        signers_fields: objSigners,
                        content: null,
                    };
                });

            const formattedTemplates = item.documents.map(detail => ({
                id: detail.id,
                name: detail.name || "",
                document_package_header_id: item.id,
                template_version_id: detail.template_version_id,
                tpl_name: detail.template?.tpl_name,
                content: detail.content,
                visibility: detail.template?.visibility,
                company_id: item.company_id,
                created_at: detail.created_at,
                updated_at: detail.updated_at,
                active: detail.active,
            }));

            const firstValidLink = item.documents.map(d => d.content).find(c => c && isValidUrl(c));

            const permissions = await checkUserPermissions(userId, item.id); 

            return {
                id: item.id,
                permissions,
                approval_status: item.approval_status,
                photo_control: photo_control ? 1 : 0,
                geolocation_control: geolocation_control ? 1 : 0,
                validation_code_control: validation_code_control ? 1 : 0,
                order: item.order,
                has_signers: item.has_signers,
                deadline_days: item.deadline_days,
                send_reminder: item.send_reminder ? 1 : 2,
                reminder_days_interval: item.reminder_days_interval,
                company_id: item.company_id,
                name: item.name,
                is_pdf: item.is_pdf ? 1 : 0,
                status: item.status,
                folder_order: item.folder_order,
                parent_id: item.parent_id,
                created_at: item.created_at,
                updated_at: item.updated_at,
                active: item.active,
                expires_in_days: item.expires_in_days,
                contract_number: item.contract_number,
                signers,
                recipients,
                has_recipients: item.has_recipients === 1 ? 1 : 2,
                recipients_later: item.recipients_later === 1 ? 1 : 2,
                templates: formattedTemplates,
                content: item.is_pdf ? firstValidLink || null : null,
                json_string: JSON.stringify({
                    document_package_header_id: item.id,
                    expires_in_days: "",
                    contract_number: "",
                    api_key: "",
                    detail: details,
                })
            };
        });

        const _data = await Promise.all(dataPromises);

        res.status(200).send({
            status: true,
            total: total,
            current_page: page,
            total_pages: Math.ceil(total / perPage),
            data: _data,
        });

    } catch (err) {
        console.error("Error fetching document packages:", err);
        res.status(500).send({
            status: false,
            message: "An internal server error occurred.",
            error: process.env.NODE_ENV === 'development' ? err.message : undefined,
        });
    }
}

function isValidUrl(urlString) {
  if (!urlString || typeof urlString !== 'string') {
    return false;
  }

  try {

    new URL(urlString);
    return true;
  } catch (error) {
    return false;
  }
}

async function getFeatures(req, res) {

    try {

        const companyId = parseInt(req.params.company_id);

        const company = await db.companies.findFirst({
            where: { id: companyId },
            select: {
                id: true,
                company_parent_id: true
            }
        });


        const storageCompanyId = company.company_parent_id || company.id;

        const features = await db.company_advanced_options.findFirst({
            where: {
                company_id: storageCompanyId
            }
        });

        return res.status(200).send({
            status: true,
            data: features,
        });



    } catch (error) {
        return res.status(404).send({
            status: false,
            message: `Error al realizar la petición: ${error}`
        });
    }
}

async function getPackageFeatures(req, res) {

    try {

        const features = await db.document_package_features.findMany({
            where: {
                document_package_header_id: parseInt(req.params.document_package_header_id),
            },
        });

        return res.status(200).send({
            status: true,
            data: features,
        });



    } catch (error) {
        return res.status(404).send({
            status: false,
            message: `Error al realizar la petición: ${error}`
        });
    }
}


async function deleteDocumentsPackagesHeader(req, res) {
    const documentPackageId = parseInt(req.params.id, 10);
    const userId = parseInt(req.params.user_id, 10); 

    try {
        const allFolderIdsToDeactivate = new Set([documentPackageId]);
        let idsToScan = [documentPackageId];

        while (idsToScan.length > 0) {
            const children = await db.document_packages_header.findMany({
                where: {
                    parent_id: { in: idsToScan },
                },
                select: {
                    id: true,
                },
            });

            const childrenIds = children.map((child) => child.id);

            if (childrenIds.length === 0) {
                break; 
            }

            childrenIds.forEach(id => allFolderIdsToDeactivate.add(id));
            idsToScan = childrenIds;
        }

        const folderIdsArray = Array.from(allFolderIdsToDeactivate);

        const relatedSigner = await db.document_packages_signers.findFirst({
            where: {
                document_package_header_id: { in: folderIdsArray },
            },
            select: {
                id: true,
            },
        });

        if (relatedSigner) {
            return res.status(400).send({
                status: false,
                message: "No es posible eliminar el grupo porque una de sus carpetas o subcarpetas tiene registros relacionados.",
            });
        }

        const updateResult = await db.document_packages_header.updateMany({
            where: {
                id: { in: folderIdsArray },
            },
            data: {
                deleted: true,
            },
        });

        const mainPackage = await db.document_packages_header.findUnique({
            where: { id: documentPackageId },
            select: { name: true },
        });

        await logHistory({
            documentPackageId: documentPackageId,
            userId: userId,
            actions: [`Se eliminó el grupo "${mainPackage.name}" y ${updateResult.count - 1} subcarpetas.`],
        });

        res.status(200).send({
            status: true,
            message: `Grupo y subcarpetas (${updateResult.count} en total) borrados exitosamente.`,
        });

    } catch (e) {
        console.error("Error al borrar el grupo de documentos:", e);
        res.status(500).send({ 
            status: false,
            message: `Error al borrar el grupo: ${e.message}`,
        });
    }
}

