       console.log(err)
    }
}

async function getCompany(companyId) {
     const company = await db.companies.findFirst({
        where: { id: parseInt(companyId) },
        select: {
            id: true,
            avatar: true,
            user_id: true,
            fiscal_name: true,
            company_name: true,
            company_parent_id: true,
            created_at: true,
            updated_at: true,
            active: true,
            type: true
        }
    });

    if (!company) return {};

    const isBranch = !!company.company_parent_id;
    const principalCompanyId = isBranch ? company.company_parent_id : company.id;

    const principal = await db.companies.findFirst({
        where: { id: principalCompanyId },
        select: {
            email: true,
            phone: true,
            address: true,
            id_number: true,
            id_type: true,
            api_key: true,
            advanced_settings: {
                select: { email_message: true }
            }
        }
    });

    return {
        id: company.id,
        avatar: company.avatar,
        user_id: company.user_id,
        fiscal_name: company.fiscal_name,
        company_name: company.company_name,
        address: principal?.address || null,
        phone: principal?.phone || null,
        email: principal?.email || null,
        id_number: principal?.id_number || null,
        id_type: principal?.id_type || null,
        api_key: principal?.api_key || null,
        created_at: company.created_at,
        updated_at: company.updated_at,
        active: company.active,
        type: company.type,
        email_message: principal?.advanced_settings?.[0]?.email_message || null
    };
}


async function generateFingerPrint() {
    const { X509Certificate } = require("crypto");

    const fs = require("fs");

    const x509 = new X509Certificate(fs.readFileSync("./my_cert.pem", "utf-8"));

    const value = x509.fingerprint;
    // display the result
    return value.replace(/:/g, "").toLowerCase();
}


