async renderPage(pageNum, scaleOverride = null) {
  try {
    if (this.isRendering && this.renderingTask) {
      try {
        await this.renderingTask.cancel();
      } catch (cancelErr) {
        console.warn('No se pudo cancelar render anterior:', cancelErr);
      }
    }

    this.isRendering = true;
    this.renderingTask = null;

    const canvas = this.$refs.pdfCanvas;
    const container = this.$refs.pdfContainer;

    if (!this.pdf || typeof this.pdf.getPage !== 'function') {
      throw new Error('Documento PDF no válido o no cargado');
    }

    const page = await this.pdf.getPage(pageNum);
    const originalViewport = page.getViewport({ scale: 1 });

    this.originalPdfWidth = originalViewport.width;
    this.originalPdfHeight = originalViewport.height;

    const baseScale = scaleOverride ?? this.currentScale ?? 1;
    const containerHeight = container.clientHeight - 32;
    const computedScale = baseScale || (containerHeight / originalViewport.height);

    this.currentScale = computedScale;

    const dpr = window.devicePixelRatio || 1;
    const viewport = page.getViewport({ scale: computedScale * dpr });

    canvas.width = viewport.width;
    canvas.height = viewport.height;
    canvas.style.width = `${viewport.width / dpr}px`;
    canvas.style.height = `${viewport.height / dpr}px`;

    const context = canvas.getContext('2d');
    const renderTask = page.render({ canvasContext: context, viewport });
    this.renderingTask = renderTask;

    await renderTask.promise;

    this.renderingTask = null;

    this.$nextTick(() => {
      const rect = canvas.getBoundingClientRect();
      this.pdfCanvasWidth = rect.width;
      this.pdfCanvasHeight = rect.height;

