                country_id: parseInt(countryId),
            },
            select: {
                id: true,
                name: true,
                field_type: true,
            }
        });

        const signers_names = signers_fields.map(field => {
            return field.name.replace(/\[\$|\]/g, '');  
        });

        const workbook = new ExcelJS.Workbook();
        const worksheet = workbook.addWorksheet('Cargue Masivo');       

        const columns = [
            { header: 'Fecha límite para realizar la firma', key: 'expires_in_days', width: 30 },
            { header: 'Número de contrato', key: 'contract_number', width: 20 },
        ];

        const doctypeColumnKeys = [];
        const documentColumnKeys = [];
        const phoneColumnKeys = [];
        const emailColumnKeys = [];

        signers_names.forEach((field, index) => {

            const match = field.match(/FIRMA(\d+)/);
            const signerNumber = match ? match[1] : '';

            columns.push({ header: `Firmante${signerNumber}_Nombre`, key: `signer${signerNumber}_name`, width: 15 });
            columns.push({ header: `Firmante${signerNumber}_Apellido`, key: `signer${signerNumber}_surname`, width: 15 });
            const emailKey = `signer${signerNumber}_email`;
            columns.push({ header: `Firmante${signerNumber}_Correo`, key: emailKey, width: 30 });
            emailColumnKeys.push(emailKey);

            const phoneKey = `signer${signerNumber}_phone`;
            columns.push({ header: `Firmante${signerNumber}_Celular`, key: phoneKey, width: 20 });
            phoneColumnKeys.push(phoneKey);

            const doctypeKey = `signer${signerNumber}_doctype`;
            columns.push({ header: `Firmante${signerNumber}_Tipo_documento`, key: doctypeKey, width: 30 });
            doctypeColumnKeys.push(doctypeKey);

            const documentKey = `signer${signerNumber}_document`;
            columns.push({ header: `Firmante${signerNumber}_Documento`, key: documentKey, width: 20 });
            documentColumnKeys.push(documentKey);
        });

        worksheet.columns = columns;
        const listWorksheet = workbook.addWorksheet('Lists', { state: 'hidden' });
        documentTypes.forEach((type, index) => {
            listWorksheet.getCell(`A${index + 1}`).value = type.name;
            listWorksheet.getCell(`B${index + 1}`).value = type.field_type;
        });

        doctypeColumnKeys.forEach(doctypeKey => {
            const column = worksheet.getColumn(doctypeKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'list',
                    allowBlank: true,
                    formulae: [`Lists!$A$1:$A$${documentTypes.length}`]
                };
            }
        });

        documentColumnKeys.forEach((documentKey, index) => {
            const doctypeKey = doctypeColumnKeys[index]; 
            const documentColumn = worksheet.getColumn(documentKey);
            const doctypeColumn = worksheet.getColumn(doctypeKey);

            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const documentCell = worksheet.getCell(rowIndex, documentColumn.number);
                const doctypeCellAddress = worksheet.getCell(rowIndex, doctypeColumn.number).address;

                documentCell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Valor inválido',
                    error: 'El documento debe ser numérico o alfanumérico y tener al menos 6 caracteres, según el tipo de documento seleccionado.',
                    formulae: [
                        `=IF(
                            INDIRECT("Lists!$B$"&MATCH(${doctypeCellAddress},Lists!$A$1:$A$${documentTypes.length},0))="numeric",
                            AND(ISNUMBER(${documentCell.address}),LEN(${documentCell.address})>=6),
                            LEN(${documentCell.address})>=6
                        )`
                    ]
                };
            }
        });

        phoneColumnKeys.forEach(phoneKey => {
            const column = worksheet.getColumn(phoneKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Celular inválido',
                    error: 'El celular debe ser numérico y tener entre 10 y 14 dígitos.',
                    formulae: [`=AND(ISNUMBER(${cell.address}),LEN(${cell.address})>=10,LEN(${cell.address})<=14)`]
                };
            }
        });

        emailColumnKeys.forEach(emailKey => {
            const column = worksheet.getColumn(emailKey);
            for (let rowIndex = 2; rowIndex <= 501; rowIndex++) {
                const cell = worksheet.getCell(rowIndex, column.number);
                cell.dataValidation = {
                    type: 'custom',
                    allowBlank: true,
                    showErrorMessage: true,
                    errorStyle: 'error',
                    errorTitle: 'Correo inválido',
                    error: 'Por favor, ingrese un correo electrónico válido.',
                    formulae: [`=AND(
                        ISERROR(FIND(" ",${cell.address})),
                        FIND("@",${cell.address})>1,
                        FIND(".",${cell.address},FIND("@",${cell.address})+1)>FIND("@",${cell.address})+1
                    )`]
                };
            }
        });

        const dateColumn = worksheet.getColumn('expires_in_days');

        dateColumn.eachCell({ includeEmpty: true }, (cell, rowNumber) => {
            if (rowNumber > 1) {
                cell.dataValidation = {
                    type: 'date',
                    allowBlank: true,
                    showErrorMessage: true,
                    operator: 'greaterThan', 
                    errorStyle: 'error',
                    errorTitle: 'Fecha inválida',
                    error: 'Por favor, ingrese una fecha igual o mayor a la fecha actual en el formato DD/MM/AAAA.',
                    formula1: '=TODAY()',
                };
                cell.numFmt = 'dd/mm/yyyy';  

            }
        });

        const tempFilePath = `./template_${Date.now()}`;

        workbook.xlsx.writeFile(tempFilePath).then(() => {
            fs.readFile(tempFilePath, (err, data) => {

              if (err) {
                console.error(err);
                res.status(500).send({
                  status: false,
                  message: "Error al generar archivo de Excel",
                });
              } else {
                res.status(200)
                  .header({
                    "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    "Content-Disposition": `attachment; filename="cargue_masivo.xlsx"`,
                    "Content-Length": data.length,
                  })
                  .send(data);
              }

              fs.unlink(tempFilePath, () => {});

            });
        }); 


    } catch (err) {
        console.log(err);
        res.status(404).send({
            status: false,
            message: err,
        });
    }
}

async function importDocumentsPackagesFields(req, res) {

    if (!req.file) {
        return res.status(400).send({
          status: false,
          message: "No se ha subido ningún archivo",
          errors: [
            {
              field_name: "file",
            },
          ],
        });
    }

    const countryId = req.body.countryId;

    const file = req.file;
    const workbook = new ExcelJS.Workbook();

    await workbook.xlsx.readFile(file.path);

    const worksheet = workbook.getWorksheet(1);
    if (!worksheet) {
        return res.status(400).send({
            status: false,
            message: "El archivo no contiene hojas válidas.",
            errors: [{ field_name: "file" }],
        });
    }

    let hasData = false;
    worksheet.eachRow((row, rowNumber) => {
        if (rowNumber > 1) {
            let rowHasRealData = false;

            row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
                if (cell.value !== null && cell.value !== '' && typeof cell.value !== 'object') {
                    rowHasRealData = true;
                }
            });

            if (rowHasRealData) {
                hasData = true;
            } else {
                console.log(`Fila ${rowNumber} solo contiene validaciones o está vacía.`);
            }
        }
    });

    if (!hasData) {
        return res.status(400).send({
            status: false,
            message: "El archivo está vacío o solo contiene validaciones de datos sin valores.",
            errors: [{ field_name: "file" }],
        });
    }

    try {
        const documentTypes = await db.identification_types.findMany({
            where: {
                country_id: parseInt(countryId),
            },
            select: {
                id: true,
                name: true,
                field_type: true,
            }
        });

        const documentTypeMap = {};
        const documentTypeIdMap = {};

        documentTypes.forEach(type => {
            documentTypeMap[type.name] = type.field_type;
            documentTypeIdMap[type.name] = type.id;
        });


        let headers = {};
        let fields = [];
        let signers = [];

        worksheet.getRow(1).eachCell((cell, colNumber) => {
            headers[cell.text] = colNumber; 
            if (cell.text.startsWith('Firmante')) {
                signers.push(cell.text);
            } else if (!['Fecha y hora límite para realizar la firma', 'Número de contrato'].includes(cell.text)) {
                fields.push(cell.text); 
            }
        });

        let dataArr = [];
        let errors = []; 

        const isValidEmail = (email) => {
            return /\S+@\S+\.\S+/.test(email);
        };

        const isValidPhoneNumber = (phone) => {
            return /^\d{10,14}$/.test(phone);
        };


        worksheet.eachRow({ includeEmpty: true }, function(row, rowNumber) {
            if (rowNumber !== 1) { 

                let isRowEmpty = true;
                row.eachCell({ includeEmpty: true }, function(cell, colNumber) {
                    if (cell.value !== null && cell.value !== '') {
                        isRowEmpty = false;
                    }
                });

                if (row.actualCellCount === 0 || row.values.every(cell => cell === null || cell === '')) {
                    return;
                }

                let errorsRow = [];

                const expiresInDaysCell = row.getCell(headers['Fecha límite para realizar la firma']);
                const expiresInDays = expiresInDaysCell ? expiresInDaysCell.value : null;

                let expiresDate;
                if (!expiresInDays) {
                    errorsRow.push(`La fecha en la fila ${rowNumber} no tiene valor.`);
                } else {
                    if (expiresInDays instanceof Date) {
                        expiresDate = expiresInDays;
                    } else if (typeof expiresInDays === 'string' || typeof expiresInDays === 'number') {
                        expiresDate = new Date(expiresInDays);
                        if (isNaN(expiresDate)) {
                            errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
                        }
                    } else {
                        errorsRow.push(`La fecha en la fila ${rowNumber} no es válida.`);
                    }

                    if (expiresDate) {
                        const today = new Date();
                        today.setHours(0, 0, 0, 0);

                        expiresDate.setHours(0, 0, 0, 0);

                        if (expiresDate < today) {
                            errorsRow.push(`La fecha en la fila ${rowNumber} debe ser igual o mayor a la fecha actual.`);
                        }
                    }
                }

                const contractNumberCell = row.getCell(headers['Número de contrato']);
                const contractNumber = contractNumberCell ? contractNumberCell.value : null;

                if (contractNumber == null || contractNumber === '') {
                    errorsRow.push(`El campo "Número de contrato" en la fila ${rowNumber} no tiene valor.`);
                }

                let dynamicFields = {};
                let signerFields = {};
                let tipoDocumentoPerSigner = {};

                Object.keys(headers).forEach((header) => {
                    const colIndex = headers[header];
                    let cell = row.getCell(colIndex);
                   let rawValue = cell ? cell.value : null;
                    let value = cleanCellValue(rawValue);

                    if (typeof value === 'object' && value && value.text) {
                        value = value.text;
                    }

                    if (value === null || value === '') {
                        errorsRow.push(`La celda "${header}" en la fila ${rowNumber} no tiene valor.`);
                    }

                    if (header.includes('Correo')) {
                        if (!isValidEmail(value)) {
                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es un correo válido.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else if (header.includes('Celular')) {
                        if (!isValidPhoneNumber(value)) {
                            errorsRow.push(`El valor en la celda "${header}" en la fila ${rowNumber} no es válido. Debe ser numérico y tener entre 10 y 14 dígitos.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else if (header.includes('Tipo_documento')) {
                        const documentTypeName = value;
                        const documentTypeId = documentTypeIdMap[documentTypeName];
                        if (!documentTypeId) {
                            errorsRow.push(`El Tipo_documento "${documentTypeName}" en la fila ${rowNumber} no es válido.`);
                        } else {
                            signerFields[header] = documentTypeId;
                            const signerKey = header.split('_')[0];
                            tipoDocumentoPerSigner[signerKey] = documentTypeId;
                        }
                    } else if (header.includes('Documento')) {
                        signerFields[header] = value;

                    } else if (signers.includes(header)) {
                        if (value === null || value === '') {
                            errorsRow.push(`El campo "${header}" en la fila ${rowNumber} no tiene valor.`);
                        } else {
                            signerFields[header] = value;
                        }
                    } else {
                        dynamicFields[header] = value;
                    }
                });

                console.log(errorsRow);
                if (errorsRow.length === 0) {


                    dataArr.push({ expiresInDays: expiresDate, contractNumber, dynamicFields, signerFields });
                } else {
                    errors = errors.concat(errorsRow);
                }
            }
        });

        fs.unlink(file.path, (err) => {
            if (err) throw err;
            console.log(`Archivo eliminado: ${file.path}`);
        });

        res.status(200).send({
            status: true,
            data: {
                data: dataArr,
                documentHeaderId: req.body.documentHeaderId,
                errors: errors,
            },
            message: "Datos recibidos correctamente",
        });

    } catch (err) {
        console.log(err);
        res.status(404).send({
            status: false,
            message: err,
        });
    }
}

function cleanCellValue(value) {
    if (value === null || value === undefined) return '';

    if (value instanceof Date) {
        return value; 
    }

    if (typeof value === 'number') {
        return value;
    }

    if (typeof value === 'boolean') {
        return value;
    }

    if (typeof value === 'string') {
        return value.trim();
    }

    if (typeof value === 'object') {

        if (Array.isArray(value.richText)) {
            return value.richText.map(v => v.text || '').join('').trim();
        }

        if (value.text) {
            return String(value.text).trim();
        }
        if (value.formula !== undefined) {
            if (value.result instanceof Date) return value.result;
            return value.result || '';
        }

        return '';
    }

    return String(value).trim();
}

