async function generateDocuments(document_package_signer, company_id, prisma) {
    try {
        const documentPackageDetail = await prisma.document_packages_signers_details_values.findMany({
            where: { 
                document_package_signer_id: parseInt(document_package_signer.id) 
            },
            select: {
                id: true,
                modified_content: true,
            }
        });

        const private_key = fs.readFileSync("./my_key.key", "utf-8");

        for (const dpd of documentPackageDetail) {
            try {
                await processDocument(dpd, private_key, company_id, prisma);
            } catch (error) {
                console.error(`Error processing document with ID ${dpd.id}:`, error);
            }
        }

    } catch (error) {
        console.log("Error al procesar document_package_signer:", error);
    }
}

async function processDocument(dpd, private_key, company_id, prisma) {
    try {
        let _html = dpd.modified_content;
        const uniqueId = crypto.randomBytes(16).toString("hex");

        const s3Key = `stored_files/${company_id}/${uniqueId}.jwt`;

        await uploadToS3(_html, private_key, s3Key);

        await prisma.document_packages_signers_details_values.update({
            where: { id: dpd.id },
            data: { s3_key: s3Key }
        });
    } catch (error) {
        console.log("Error al procesar el documento:", error);
    }
}

async function uploadToS3( html, private_key, key) {
    try {
        const payload = { pdf: html };
        const encryptedBuffer = jwt.sign(payload, private_key, { algorithm: "RS512" });

        const uploadParams = {
            Bucket: process.env.S3_BUCKET,
            Key: key,
            Body: encryptedBuffer,
            ContentType: 'application/jwt',
        };

        await s3Client.send(new PutObjectCommand(uploadParams));

        return `https://${uploadParams.Bucket}.s3.amazonaws.com/${key}`;

    } catch (error) {
        console.log("Error al subir el archivo a S3:", error);
    }
}


async function updateContent2(
    document_package_signer_detail_value_id,
    document_package_detail_id,
    fields,
    fields_values,
    prisma
) {
    var tmpFields = fields.split("|");

    var tmpFieldsValues = fields_values.split("|");

    var documentPackageDetail = await prisma.document_packages_signers_details_values.findFirst({
        where: {
            id: document_package_signer_detail_value_id,
        },
        select: {
           modified_content: true,
        }
    });

    try {
        if (documentPackageDetail) {
            var content = documentPackageDetail.modified_content;

            for (var i = 0; i < tmpFields.length; i++) {

                var f = new RegExp("{\\s*" + tmpFields[i] + "\\s*}", "g");

                content = content.replace(f, tmpFieldsValues[i]);
            }

            var documentPackageDetail = {
                modified_content: content,
            };


            await prisma.document_packages_signers_details_values.updateMany({
                where: {
                    id: parseInt(document_package_signer_detail_value_id),
                },
                data: documentPackageDetail,
            });
        }
    } catch (err) {
       console.log(err)
    }
}

async function getCompany(companyId) {
     const company = await db.companies.findFirst({
        where: { id: parseInt(companyId) },
        select: {
            id: true,
            avatar: true,
            user_id: true,
            fiscal_name: true,
            company_name: true,
            company_parent_id: true,
            created_at: true,
            updated_at: true,
            active: true,
            type: true
        }
    });

    if (!company) return {};

    const isBranch = !!company.company_parent_id;
    const principalCompanyId = isBranch ? company.company_parent_id : company.id;

    const principal = await db.companies.findFirst({
        where: { id: principalCompanyId },
        select: {
            email: true,
            phone: true,
            address: true,
            id_number: true,
            id_type: true,
            api_key: true,
            advanced_settings: {
                select: { email_message: true }
            }
        }
    });

    return {
        id: company.id,
        avatar: company.avatar,
        user_id: company.user_id,
        fiscal_name: company.fiscal_name,
        company_name: company.company_name,
        address: principal?.address || null,
        phone: principal?.phone || null,
        email: principal?.email || null,
        id_number: principal?.id_number || null,
        id_type: principal?.id_type || null,
        api_key: principal?.api_key || null,
        created_at: company.created_at,
        updated_at: company.updated_at,
        active: company.active,
        type: company.type,
        email_message: principal?.advanced_settings?.[0]?.email_message || null
    };
}


async function generateFingerPrint() {
    const { X509Certificate } = require("crypto");

    const fs = require("fs");

    const x509 = new X509Certificate(fs.readFileSync("./my_cert.pem", "utf-8"));

    const value = x509.fingerprint;
    // display the result
    return value.replace(/:/g, "").toLowerCase();
}


