                                firstname: signerFields[`Firmante${i}_Nombre`] || '',
                                lastname: signerFields[`Firmante${i}_Apellido`] || '',
                                email: signerFields[`Firmante${i}_Correo`] || '',
                                id_type: signerFields[`Firmante${i}_Tipo_documento`] || '',
                                id_number: signerFields[`Firmante${i}_Documento`] || ''
                            };

                            usedOrders.add(realIndex); 

                            realIndex++; 
                        }


                        for (const key in array.dynamicFields) {

                            const fields_data = array.dynamicFields[key];
                            var fields = key;
                            var fields_values = fields_data;

                            json = {
                                fields: fields,
                                value: fields_values,
                            };

                            jsonArray.push(json);

                        }

                        for (const key in signers_updated) {

                            if (signers_updated.hasOwnProperty(key)) {

                                const signer = signers_updated[key];
                                const correspondingUser = users.find((user) => user.email.toLowerCase().trim() == signer.email.toLowerCase().trim());
                                document_package_users.push({user: correspondingUser, order: key});
                            }
                        }

                        try {

                            let fingerprint = await generateFingerPrint();
                            const date = obj.expiresInDays; 

                            //  const [year, month, day] = date.split('-');
                            const send_reminder = req.body.sendReminder;
                            const reminder_days_interval = req.body.reminder_days_interval;

                            const date_formatted = new Date(date).toISOString();

                             document_packages_signers = await prisma.document_packages_signers.create({
                                data: {
                                    document_package_header_id: documentPackageHeader.id,
                                    user_id:  parseInt(users[0].id) || parseInt(users[1].id),
                                    company_id: company_id,
                                    status: "send",
                                    token: "",
                                    sent_sign_request_at:  new Date(),
                                    fingerprint: fingerprint.replace(":", ""),
                                    ip_address: req.ip,
                                    from_api: 0,
                                    // rejected_at: req.body.id_type,
                                    active: "1",
                                    reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
                                    send_reminder: send_reminder == 1 ? true : false,
                                    expires_in_days: date_formatted,
                                    contract_number: String(obj.contractNumber),
                                    created_at: new Date(),
                                    updated_at: new Date()
                                },
                            });

                            const recipients = req.body.recipients;
                            if (Array.isArray(recipients) && recipients.length > 0) {
                                for (let i = 0; i < recipients.length; i++) {
                                    const recipient = recipients[i];

                                    await prisma.request_recipients.create({
                                        data: {
                                            document_package_signer_id: document_packages_signers.id,
                                            type: 1,
                                            email: recipient.email,
                                            created_at: new Date(),
                                            updated_at: new Date(),
                                        },
                                    });

                                    await prisma.document_packages_signers_logs.create({
                                        data: {
                                            document_package_signer_id: document_packages_signers.id,
                                            event_description: `Destinatario agregado: ${recipient.email}`,
                                            ip_address: req.ip ? req.ip : null,
                                            performed_by_user_id: parseInt(req.body.user_id_creator),
                                            created_at: new Date(),
                                        },
                                    });
                                }
                            }

                            await prisma.document_packages_signers_logs.create({
                                data: {
                                    document_package_signer_id: parseInt(document_packages_signers.id),
                                    event_description: "Solicitud de firma enviada",
                                    ip_address: req.ip ? req.ip : null,
                                    performed_by_user_id: parseInt(req.body.user_id_creator),
                                    created_at: new Date(),
                                },
                            });


                            documentIds.push(document_packages_signers.id);


                            if(document_packages_signers) {

                                var arrFields = [];
                                var arrFieldsValues = [];

                                for (let i = 0; i < jsonArray.length; i++) {
                                    const e = jsonArray[i];

                                    arrFields.push(e.fields);

                                    arrFieldsValues.push(e.value);
                                }

                                arrFields = arrFields.join("|");
                                arrFieldsValues = arrFieldsValues.join("|");

                                for (let j = 0; j < document_package_details.length; j++) {

                                    const detalleId = parseInt(document_package_details[j].id);

                                    var documentPackageDetail = await prisma.document_packages_details.findFirst({
                                        where: {
                                            id: detalleId,
                                            active: "1"
                                        },
                                        include: {
                                            template: {
                                                select: {
                                                    tpl_name: true,
                                                    visibility: true,
                                                    document_type_id: true,
                                                    content: true,

                                                }
                                            }
                                        }
                                    });

                                    let _html = documentPackageDetail.template.content;

                                    for (let u = 0; u < document_package_users.length; u++) {

                                        const user_up =  actual_users.find((user) => user.id == document_package_users[u].user.id);

                                        const order = document_package_users[u].order.replace('Firmante', '');

                                        const modified_content = createModifiedContent(user_up); 

                                        _html = replaceSignature(_html, order, modified_content);

                                    }


                                    if (!documentPackageDetail) {
                                        console.log("detalleId2", detalleId)
                                        throw new Error(`El id_detalle_grupo_documento ${detalleId} ingresado no existe`);
                                    } else  {


                                        let detail_values =  await prisma.document_packages_signers_details_values.create({
                                            data: {
                                                document_package_detail_id: detalleId,
                                                document_package_signer_id: parseInt(document_packages_signers.id),
                                                company_id: company_id,
                                                name: documentPackageDetail.template.tpl_name,
                                                visibility: documentPackageDetail.template.visibility,
                                                document_type_id: documentPackageDetail.template.document_type_id,
                                                fields: arrFields,
                                                fields_values: arrFieldsValues,
                                                signers_fields: documentPackageDetail.signers_fields,
                                                modified_content: _html,
                                                created_at: new Date(),
                                                updated_at: new Date()
                                            },
                                        });

                                        await updateContent2(
                                            detail_values.id,
                                            detalleId,
                                            arrFields,
                                            arrFieldsValues,
                                            prisma
                                        );
                                    }


                                }


                            } 

                        }   catch (err) { 
                            console.log(err)
                            throw new Error('document_packages_signers_details_values', err);
                        }
                        try {

                            let sendRequest = true;

                            for (let i = 0; i < document_package_users.length; i++) {

                                const user = document_package_users[i].user;

                                const original_order = document_package_users[i].order;

                                const order = original_order.replace('Firmante', '');

                                var token = service.createCustomToken({
                                    id: user.id,
                                    document_package_signer_id: document_packages_signers.id,
                                });

                                let fingerprint = await generateFingerPrint();



                                const date_formatted = new Date(obj.expiresInDays).toISOString();
                                await prisma.document_signers.create({
                                    data: {
                                        document_package_signer_id: document_packages_signers.id,
                                        user_id: parseInt(user.id),
                                        status: "send",
                                        token: token,
                                        sent_sign_request_at:  new Date(),
                                        expires_in_days: date_formatted,
                                        order: parseInt(order),
                                        fingerprint: fingerprint.replace(":", ""),
                                        created_at: new Date(),
                                        updated_at: new Date()
                                    },
                                });

                                var _url = process.env.ENV_URL + token;

                                let date = document_packages_signers.expires_in_days.toLocaleDateString('es-ES');
                                let time = document_packages_signers.expires_in_days.toLocaleTimeString();

                                if (documentPackageHeader.order === 1 && parseInt(order) === 1) {
                                    requestToSending.push({ 
                                        email: user.email, 
                                        company: company, 
                                        firstname: user.firstname, 
                                        lastname: user.lastname, 
                                        passwordGenerated: passwordGenerated, 
                                        date: date, 
                                        time: time, 
                                        _url: _url, 
                                        company_email: company.email, 
                                        documentPackageHeader: documentPackageHeader, 
                                        sendRequest: sendRequest 
                                    });
                                }

                                if (documentPackageHeader.order === 2) {
                                    requestToSending.push({ 
                                        id: user.id,
                                        document_package_signer_id: document_packages_signers.id,
                                        email: user.email, 
                                        company: company, 
                                        firstname: user.firstname, 
                                        lastname: user.lastname, 
                                        passwordGenerated: passwordGenerated, 
                                        date: date, 
                                        time: time, 
                                        _url: _url, 
                                        company_email: company.email, 
                                        documentPackageHeader: documentPackageHeader, 
                                        sendRequest: sendRequest 
                                    });
                                }

                            }
                        } catch (e) {
                            console.log(e)
                            throw new Error('document_signers', e);
                        }

                        try {
                            await generateDocuments(document_packages_signers, company_id, prisma)
                        } catch (error) {
                            throw new Error('generateDocuments', error);                
                        }

                    },

                    {
                        maxWait: 50000, 
                        timeout: 100000, 
                    }
                    ).catch((error) => {
                        console.error("Error en la transacción: ", error);
                        throw new Error('Error en la transacción:', error);       
                    });

                }



                requestSending = true;

                if (requestSending) {
                    for (let i = 0; i < requestToSending.length; i++) {
                        const user = requestToSending[i];

                        if(user.sendRequest) {                   
                            await service.sendSolicitudFirma(
                                user.email,
                                user.company.avatar,
                                user.firstname + " " + user.lastname,
                                user.company.fiscal_name,
                                user.company.fiscal_name,
                                user.passwordGenerated,
                                user.date,
                                user.time,
                                user._url,
                                user.company_email,
                                user.documentPackageHeader.name,
                                user.company.email_message,
                                user.id,
                                user.company.id,
                                user.document_package_signer_id
                            );
                        }

                    }
                }


                res.status(200).send({
                    status: true,
                    data: {
                        request_id: documentIds,
                        count: documentIds.length,
                    },
                    message: "Solicitudes enviadas exitosamente",
                }); 



            } catch (err) {
                console.log(err)
                res.status(404).send({
                    status: false,
                    message: err,
                });
            }
        }

    }

}


async function generateDocuments(document_package_signer, company_id, prisma) {
    try {
        const documentPackageDetail = await prisma.document_packages_signers_details_values.findMany({
            where: { 
                document_package_signer_id: parseInt(document_package_signer.id) 
            },
            select: {
                id: true,
                modified_content: true,
            }
        });

        const private_key = fs.readFileSync("./my_key.key", "utf-8");

        for (const dpd of documentPackageDetail) {
            try {
                await processDocument(dpd, private_key, company_id, prisma);
            } catch (error) {
                console.error(`Error processing document with ID ${dpd.id}:`, error);
            }
        }

    } catch (error) {
        console.log("Error al procesar document_package_signer:", error);
    }
}

async function processDocument(dpd, private_key, company_id, prisma) {
    try {
        let _html = dpd.modified_content;
        const uniqueId = crypto.randomBytes(16).toString("hex");

        const s3Key = `stored_files/${company_id}/${uniqueId}.jwt`;

        await uploadToS3(_html, private_key, s3Key);

        await prisma.document_packages_signers_details_values.update({
            where: { id: dpd.id },
            data: { s3_key: s3Key }
        });
    } catch (error) {
        console.log("Error al procesar el documento:", error);
    }
}

async function uploadToS3( html, private_key, key) {
    try {
        const payload = { pdf: html };
        const encryptedBuffer = jwt.sign(payload, private_key, { algorithm: "RS512" });

        const uploadParams = {
            Bucket: process.env.S3_BUCKET,
            Key: key,
            Body: encryptedBuffer,
            ContentType: 'application/jwt',
        };

        await s3Client.send(new PutObjectCommand(uploadParams));

        return `https://${uploadParams.Bucket}.s3.amazonaws.com/${key}`;

    } catch (error) {
        console.log("Error al subir el archivo a S3:", error);
    }
}


async function updateContent2(
    document_package_signer_detail_value_id,
    document_package_detail_id,
    fields,
    fields_values,
    prisma
) {
    var tmpFields = fields.split("|");

    var tmpFieldsValues = fields_values.split("|");

    var documentPackageDetail = await prisma.document_packages_signers_details_values.findFirst({
        where: {
            id: document_package_signer_detail_value_id,
        },
        select: {
           modified_content: true,
        }
    });

    try {
        if (documentPackageDetail) {
            var content = documentPackageDetail.modified_content;

            for (var i = 0; i < tmpFields.length; i++) {

                var f = new RegExp("{\\s*" + tmpFields[i] + "\\s*}", "g");

                content = content.replace(f, tmpFieldsValues[i]);
            }

            var documentPackageDetail = {
                modified_content: content,
            };


            await prisma.document_packages_signers_details_values.updateMany({
                where: {
                    id: parseInt(document_package_signer_detail_value_id),
                },
                data: documentPackageDetail,
            });
        }
    } catch (err) {
       console.log(err)
    }
}

async function getCompany(companyId) {
     const company = await db.companies.findFirst({
        where: { id: parseInt(companyId) },
        select: {
            id: true,
            avatar: true,
            user_id: true,
            fiscal_name: true,
            company_name: true,
            company_parent_id: true,
            created_at: true,
            updated_at: true,
            active: true,
            type: true
        }
    });

    if (!company) return {};

    const isBranch = !!company.company_parent_id;
    const principalCompanyId = isBranch ? company.company_parent_id : company.id;

    const principal = await db.companies.findFirst({
        where: { id: principalCompanyId },
        select: {
            email: true,
            phone: true,
            address: true,
            id_number: true,
            id_type: true,
            api_key: true,
            advanced_settings: {
                select: { email_message: true }
            }
        }
    });

    return {
        id: company.id,
        avatar: company.avatar,
        user_id: company.user_id,
        fiscal_name: company.fiscal_name,
        company_name: company.company_name,
        address: principal?.address || null,
        phone: principal?.phone || null,
        email: principal?.email || null,
        id_number: principal?.id_number || null,
        id_type: principal?.id_type || null,
        api_key: principal?.api_key || null,
        created_at: company.created_at,
        updated_at: company.updated_at,
        active: company.active,
        type: company.type,
        email_message: principal?.advanced_settings?.[0]?.email_message || null
    };
}


async function generateFingerPrint() {
    const { X509Certificate } = require("crypto");

    const fs = require("fs");

    const x509 = new X509Certificate(fs.readFileSync("./my_cert.pem", "utf-8"));

    const value = x509.fingerprint;
    // display the result
    return value.replace(/:/g, "").toLowerCase();
}


