   168→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
   169→    const pdfDoc = pdfBuffer;
   170→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
   171→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
   172→    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
   173→    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
   174→    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
   175→    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
   176→    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
   177→    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);
   178→
   179→    // Separar campos de firma/qr de variables
   180→    const signatureFields = fields.filter(f => f.type !== 'variable');
   181→    const variableFieldsList = fields.filter(f => f.type === 'variable');
   182→
   183→    // Procesar campos de firma (lógica existente sin cambios)
   184→    await Promise.all(signatureFields.map(async (field) => {
   185→        const { pageNumber, top, left, width, height, name } = field;
   186→        const page = pdfDoc.getPage(pageNumber - 1);
   187→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
   188→        const textHeight = helveticaFont.heightAtSize(12);
   189→
   190→        const x = left + (width / 2) - (textWidth / 2) - 15;
   191→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
   192→
   193→        page.drawText(name, {
   194→            x: x,
   195→            y: y + 8,
   196→            size: 12,
   197→            font: helveticaFont
   198→        });
   199→
   200→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
   201→
   202→        if (signer) {
   203→            const fullName = `${signer.nombres} ${signer.apellidos}`;
   204→            const docType = await getDocumentTypeName(signer.tipo_documento);
   205→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
   206→
   207→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
   208→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
   209→
   210→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
   211→
   212→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
   213→
   214→            page.drawText(fullName, {
   215→                x: xFullName,
   216→                y: y - textHeight - 8,
   217→                size: 10,
   218→                font: timesRomanFont
   219→            });
   220→
   221→            page.drawText(docTypeAndNumber, {
   222→                x: xDocTypeAndNumber,
   223→                y: y - textHeight - 22,
   224→                size: 10,
   225→                font: timesRomanFont
   226→            });
   227→        }
   228→    }));
   229→
   230→    // Procesar campos de variables
   231→    for (const field of variableFieldsList) {
   232→        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
   233→        const page = pdfDoc.getPage(pageNumber - 1);
   234→
   235→        const varName = name.replace(/\[\$|\]/g, '');
   236→        const value = variableValues[varName] || '';
   237→
   238→        if (!value) continue;
   239→
   240→        const isBold = fontWeight && parseInt(fontWeight) >= 600;
   241→        const isItalic = fontStyle === 'italic';
   242→        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');
   243→
   244→        let selectedFont;
   245→        if (isSerif) {
   246→            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
   247→            else if (isBold) selectedFont = timesRomanBoldFont;
   248→            else if (isItalic) selectedFont = timesRomanItalicFont;
   249→            else selectedFont = timesRomanFont;
   250→        } else {
   251→            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
   252→            else if (isBold) selectedFont = helveticaBoldFont;
   253→            else if (isItalic) selectedFont = helveticaObliqueFont;
   254→            else selectedFont = helveticaFont;
   255→        }
   256→
   257→        const maxFontSize = Math.min(height * 0.6, 32);
   258→        let fontSize = Math.max(8, maxFontSize);
   259→
   260→        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   261→        while (textWidth > width - 4 && fontSize > 6) {
   262→            fontSize -= 0.5;
   263→            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   264→        }
   265→
   266→        const textHeight = selectedFont.heightAtSize(fontSize);
   267→
   268→        const x = left + (width / 2) - (textWidth / 2);
   269→        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);
   270→
   271→        let color = rgb(0.39, 0.39, 0.38);
   272→        if (fontColor && fontColor.startsWith('#')) {
   273→            const hex = fontColor.replace('#', '');
   274→            const r = parseInt(hex.substring(0, 2), 16) / 255;
   275→            const g = parseInt(hex.substring(2, 4), 16) / 255;
   276→            const b = parseInt(hex.substring(4, 6), 16) / 255;
   277→            color = rgb(r, g, b);
   278→        }
   279→
   280→        page.drawText(value, {
   281→            x: x,
   282→            y: y,
   283→            size: fontSize,
   284→            font: selectedFont,
   285→            color: color,
   286→        });
   287→    }
   288→
   289→    return await pdfDoc.save();
   290→}
