   181→    const variableFieldsList = fields.filter(f => f.type === 'variable');
   182→
   183→    // Procesar campos de firma (lógica existente sin cambios)
   184→    await Promise.all(signatureFields.map(async (field) => {
   185→        const { pageNumber, top, left, width, height, name } = field;
   186→        const page = pdfDoc.getPage(pageNumber - 1);
   187→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
   188→        const textHeight = helveticaFont.heightAtSize(12);
   189→
   190→        const x = left + (width / 2) - (textWidth / 2) - 15;
   191→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
   192→
   193→        page.drawText(name, {
   194→            x: x,
   195→            y: y + 8,
   196→            size: 12,
   197→            font: helveticaFont
   198→        });
   199→
   200→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
   201→
   202→        if (signer) {
   203→            const fullName = `${signer.nombres} ${signer.apellidos}`;
   204→            const docType = await getDocumentTypeName(signer.tipo_documento);
   205→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
